html:
{%- import "costeo_yelke/templates/print/oc_yelke.html" as oc -%}
{#- Movimiento de material: envío a taller, traspaso, entrada o salida de almacén. Diseño: templates/print/oc_yelke.html -#}
{%- set titulos = {"Send to Subcontractor": "Envío a taller", "Material Transfer": "Traspaso de material",
    "Material Transfer for Manufacture": "Traspaso a producción", "Material Receipt": "Entrada de material",
    "Material Issue": "Salida de material", "Manufacture": "Producción", "Repack": "Reempaque",
    "Material Consumption for Manufacture": "Consumo de producción"} -%}
{%- set titulo = titulos.get(doc.purpose) or doc.stock_entry_type or "Movimiento de material" -%}
{%- set origenes = doc.items | map(attribute="s_warehouse") | select | unique | list -%}
{%- set destinos = doc.items | map(attribute="t_warehouse") | select | unique | list -%}
{%- set con_costo = doc.purpose in ("Material Receipt", "Material Issue") -%}
{{ oc.estilos() }}
{{ oc.membrete_encabezado(doc, no_letterhead, print_settings, titulo) }}
<div class="pdf-container">
{{ oc.marca_borrador(doc) }}
{%- if doc.get("supplier") %}
{%- set tercero = {"etiqueta": "Taller", "nombre": doc.supplier_name or doc.supplier, "rfc": rfc_tercero("Supplier", doc.supplier), "direccion": direccion_lineas(doc.get("supplier_address"))} %}
{%- else %}
{%- set tercero = {"etiqueta": "Movimiento", "nombre": titulo, "rfc": "", "direccion": [doc.remarks] if doc.remarks else []} %}
{%- endif %}
{{ oc.datos(doc, tercero,
    [("Fecha", fecha_corta(doc.posting_date)),
     ("Encargo", doc.get("subcontracting_order")),
     ("Orden de maquila", doc.get("purchase_order")),
     ("Sale de", origenes[0] if origenes | length == 1 else None),
     ("Llega a", destinos[0] if destinos | length == 1 else None),
     ("Renglones", doc.items | length)]) }}
<table class="items-table">
    <thead><tr>
        <th style="width:6mm">#</th><th>Artículo</th>
        {% if origenes | length > 1 %}<th style="width:34mm">Sale de</th>{% endif %}
        {% if destinos | length > 1 %}<th style="width:34mm">Llega a</th>{% endif %}
        <th class="text-right" style="width:26mm">Cantidad</th>
        {% if con_costo %}<th class="text-right" style="width:22mm">Costo</th><th class="text-right" style="width:27mm">Importe</th>{% endif %}
    </tr></thead>
    <tbody>
    {% for row in doc.items %}
        <tr>
            <td class="muted">{{ row.idx }}</td>
            <td>{{ oc.celda_articulo(row) }}</td>
            {% if origenes | length > 1 %}<td class="muted">{{ row.s_warehouse or "—" }}</td>{% endif %}
            {% if destinos | length > 1 %}<td class="muted">{{ row.t_warehouse or "—" }}</td>{% endif %}
            <td class="num">{{ cantidad_uom(row.qty, row.uom or row.stock_uom) }}</td>
            {% if con_costo %}<td class="num">{{ row.get_formatted("basic_rate", doc) }}</td><td class="num"><b>{{ row.get_formatted("basic_amount", doc) }}</b></td>{% endif %}
        </tr>
    {% endfor %}
    </tbody>
</table>
{% if con_costo %}{{ oc.total_simple("Total", doc.get_formatted("total_incoming_value") if doc.purpose == "Material Receipt" else doc.get_formatted("total_outgoing_value")) }}{% endif %}
{{ oc.cierre(doc, mostrar_pagos=false, mostrar_totales=false) }}
</div>
{{ oc.membrete_pie(doc, no_letterhead, print_settings) }}
